const separator=(current:Message, previous?:Message)=>!previous || new Date(current.created_at).toDateString()!==new Date(previous.created_at).toDateString() || new Date(current.created_at).getTime()-new Date(previous.created_at).getTime()>3600000;
const callDetails=(body:string)=>{
 const group=body.match(/^Group (voice|video) call • ([^•]+) • (\d+) members? joined$/i);
 if(group)return {mode:group[1].toLowerCase(),result:group[2].trim(),members:Number(group[3]),group:true};
 const direct=body.match(/^(Voice|Video) call • (.+)$/i);
 if(direct)return {mode:direct[1].toLowerCase(),result:direct[2].trim(),members:0,group:false};
 return null;
};
